rules.logic:
if (element.dataset.moved === 'true') return;
element.dataset.moved = 'true';

var communityLink = element.querySelector('.need-more-help-option');
if (!communityLink) return;

var clonedLink = communityLink.cloneNode(true);

// Style the moved link to look like a sidebar option
clonedLink.style.display = 'flex';
clonedLink.style.alignItems = 'center';
clonedLink.style.gap = '12px';
clonedLink.style.padding = '12px 16px';
clonedLink.style.marginTop = '12px';
clonedLink.style.marginBottom = '16px';
clonedLink.style.borderRadius = '8px';
clonedLink.style.backgroundColor = '#f1f3f4';
clonedLink.style.textDecoration = 'none';
clonedLink.style.color = 'inherit';
clonedLink.style.flexDirection = 'row';

// Insert after the h1 in the article-container
var articleContainer = element.closest('.main-content')?.querySelector('.article-container');
if (articleContainer) {
    var h1 = articleContainer.querySelector('h1');
    if (h1 && h1.nextSibling) {
        articleContainer.insertBefore(clonedLink, h1.nextSibling);
    } else if (h1) {
        articleContainer.appendChild(clonedLink);
    }
}

// Hide the original need-more-help-container at the bottom
element.style.display = 'none';
